import json,os
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in __import__('re').finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
demo=G['Demo pair 1 input']; demo_out=G['Demo pair 1 output']

def objects(g):
    h,w=len(g),len(g[0]); seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            if g[r][c] and (r,c) not in seen:
                col=g[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
                while stack:
                    x,y=stack.pop(); cells.append((x,y))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<h and 0<=ny<w and g[nx][ny]==col and (nx,ny) not in seen:
                            seen.add((nx,ny)); stack.append((nx,ny))
                objs.append((col,cells))
    return objs

def norm(cells):
    mr=min(r for r,c in cells); mc=min(c for r,c in cells)
    return frozenset((r-mr,c-mc) for r,c in cells)

def transform(g):
    objs=objects(g)
    from collections import defaultdict
    byshape=defaultdict(list)
    for col,cells in objs: byshape[norm(cells)].append((col,cells))
    out=[row[:] for row in g]
    for shape,members in byshape.items():
        if len(members)<2: continue
        colors=[c for c,_ in members]
        non1=[c for c in colors if c!=1]
        if 1 in colors and non1 and len(set(non1))==1:
            for col,cells in members:
                if col==1:
                    for r,c in cells: out[r][c]=non1[0]
    return out

